// Strip WEBVTT markup to plain text, then re-attach the full payload.
const raw = $json.meeting_transcription || "";
const clean = raw
  .replace(/WEBVTT/g, "")
  .replace(/[0-9a-f-]+\/\d+-\d+/g, "")
  .replace(/\d{2}:\d{2}:\d{2}\.\d{3} --> .*/g, "")
  .replace(/<\/?v[^>]*>/g, "")
  .replace(/\r\n|\r|\n/g, " ")
  .replace(/\s{2,}/g, " ")
  .trim();
const base = $('Parse Payload').item.json;
return [{ json: { ...base, transcript_clean: clean } }];

