// Render the agent's structured output into the plain-text report (manager-facing).
const base = $('Parse Payload').item.json;
const data = $json.output || {};
const lines = ['EOD Report  ' + (base.date || ''), ''];
for (const b of (data.buildings || [])) {
  lines.push(String(b.building || '').toUpperCase());
  lines.push('');
  for (const w of (b.wings || [])) {
    lines.push('  ' + (w.wing || ''));
    const systems = w.systems || (w.bullets ? w.bullets.map(x => ({ system: '', summary: x, details: [] })) : []);
    for (const sys of systems) {
      const name = String(sys.system || '').trim();
      const summary = String(sys.summary || '').trim();
      lines.push('    • ' + (name ? (name + ' — ' + summary) : summary));
      for (const d of (sys.details || [])) lines.push('        – ' + String(d).trim());
    }
    lines.push('');
  }
}
const text = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
return [{ json: {
  report_text: text,
  report_data: data,
  date: base.date || '',
  building_names: base.building_names || [],
  email_enabled: base.email_enabled === true
} }];

// Email-only: render the structured data into a clean, email-client-safe HTML email.
const data = $json.report_data || {};
const date = $json.date || '';
const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const BRAND = '#0ea5e9';
let sec = '';
for (const b of (data.buildings || [])) {
  const isGen = /^general/i.test(String(b.building || ''));
  sec += `<div style="font-size:15px;font-weight:700;letter-spacing:.03em;color:#0b1324;text-transform:uppercase;border-bottom:2px solid ${BRAND};padding-bottom:6px;margin:22px 0 8px;">${esc(b.building)}</div>`;
  for (const w of (b.wings || [])) {
    sec += `<div style="font-size:13px;font-weight:600;color:${isGen ? '#475569' : '#0369a1'};margin:12px 0 4px;">${esc(w.wing)}</div>`;
    const systems = w.systems || (w.bullets ? w.bullets.map(x => ({ system:'', summary:x, details:[] })) : []);
    for (const sys of systems) {
      const name = String(sys.system || '').trim();
      const summary = esc(sys.summary || '');
      const head = name ? `<strong>${esc(name)}</strong> &mdash; ${summary}` : summary;
      sec += `<div style="font-size:13.5px;color:#1f2937;margin:7px 0 1px;">&bull; ${head}</div>`;
      const details = sys.details || [];
      if (details.length) {
        sec += `<ul style="margin:1px 0 4px;padding-left:34px;">`;
        for (const d of details) sec += `<li style="font-size:12.5px;color:#475569;line-height:1.5;margin:1px 0;">${esc(d)}</li>`;
        sec += `</ul>`;
      }
    }
  }
}
const html = `<div style="font-family:'Segoe UI',Arial,Helvetica,sans-serif;max-width:720px;margin:0 auto;background:#ffffff;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;">
  <div style="background:#0b1324;padding:20px 26px;">
    <div style="font-size:11px;font-weight:700;letter-spacing:.18em;color:${BRAND};text-transform:uppercase;">Commissioning Program</div>
    <div style="font-size:21px;font-weight:700;color:#ffffff;margin-top:4px;">End-of-Day Report</div>
    <div style="font-size:13px;color:#94a3b8;margin-top:2px;">${esc(date)}</div>
  </div>
  <div style="padding:4px 26px 18px;">${sec}</div>
  <div style="padding:14px 26px;border-top:1px solid #e2e8f0;font-size:11px;color:#94a3b8;">Automatically generated from EPMS Cx tracker data.</div>
</div>`;
return [{ json: { ...$json, report_html: html } }];
